<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$id=(int)($_GET['id']??0);
$stmt=db()->prepare("SELECT g.*,u.full_name AS contributor_name,(SELECT COUNT(*) FROM saved_gems WHERE gem_id=g.id) AS saves,(SELECT COUNT(*) FROM gem_likes WHERE gem_id=g.id) AS likes FROM gems g JOIN users u ON u.id=g.user_id WHERE g.id=? AND (g.status='approved' OR g.user_id=? OR ?=1) LIMIT 1");
$stmt->execute([$id,(int)(current_user()['id']??0),is_admin()?1:0]);$gem=$stmt->fetch();
if(!$gem){http_response_code(404);exit('Gem not found.');}
$images=gem_images($id);$stmt=db()->prepare("SELECT r.*,u.full_name,(SELECT COUNT(*) FROM review_likes rl WHERE rl.review_id=r.id) AS likes FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.gem_id=? AND (r.status='approved' OR r.user_id=?) ORDER BY r.status='approved' DESC,r.created_at DESC");$stmt->execute([$id,(int)(current_user()['id']??0)]);$reviews=$stmt->fetchAll();
$pageTitle=$gem['title'];require __DIR__.'/includes/header.php';
