<section class="detail-hero"><img src="<?=e(gem_image_url($gem,$images))?>" alt="<?=e($gem['title'])?>" onerror="this.onerror=null;this.src='<?=asset('images/gem-placeholder.svg')?>'"><div class="detail-overlay"></div><div class="detail-title"><span class="eyebrow" style="color:#fff"><?=e($gem['activity_type'])?></span><h1><?=e($gem['title'])?></h1><p>⌖ <?=e($gem['location'])?></p></div>
<div class="detail-actions"><?php if(is_logged_in()):?><form method="post" action="<?=url('toggle-like.php')?>"><?=csrf_field()?><input type="hidden" name="gem_id" value="<?=$id?>"><input type="hidden" name="return_to" value="gem.php?id=<?=$id?>"><button class="icon-btn<?=is_gem_liked($id)?' active':''?>" title="Like">♥</button></form><form method="post" action="<?=url('toggle-save.php')?>"><?=csrf_field()?><input type="hidden" name="gem_id" value="<?=$id?>"><input type="hidden" name="return_to" value="gem.php?id=<?=$id?>"><button class="icon-btn<?=is_gem_saved($id)?' active':''?>" title="Save">♡</button></form><?php endif;?></div></section>
