<div class="detail-layout"><main>
<div class="content-card"><span class="eyebrow">Vibe & Activity</span><div class="tag-row"><?php foreach(tag_list($gem['vibes']) as $tag):?><span class="tag"><?=e($tag)?></span><?php endforeach;?><span class="tag"><?=e($gem['activity_type'])?></span></div><h2>About This Place</h2><p><?=nl2br(e($gem['description']))?></p></div>
<div class="content-card"><h2>Location</h2><div class="location-box"><div><div style="font-size:2rem">⌖</div><strong><?=e($gem['location'])?></strong><p class="muted"><?=e($gem['city'])?></p><a class="btn btn-ghost btn-sm" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=<?=urlencode($gem['location'])?>">Open in Maps</a></div></div></div>
