<div class="review-list"><?php if($reviews):foreach($reviews as $review):?><article class="review-card"><div class="review-head"><div class="review-user"><span class="avatar"><?=e(mb_substr($review['full_name'],0,1))?></span><div><strong><?=e($review['full_name'])?></strong> <?php if($review['status']!=='approved'):?><span class="status-badge status-<?=e($review['status'])?>"><?=e(ucfirst($review['status']))?></span><?php endif;?><br><small><?=e(date('Y-m-d',strtotime($review['created_at'])))?><?=$review['is_edited']?' · edited':''?></small></div></div><span class="stars"><?=e(render_stars((float)$review['rating']))?></span></div><p><?=e($review['comment']?:'No written comment.')?></p><?php if(is_logged_in()&&$review['status']==='approved'):?><form method="post" action="<?=url('toggle-review-like.php')?>" class="inline-form"><?=csrf_field()?><input type="hidden" name="review_id" value="<?=(int)$review['id']?>"><input type="hidden" name="gem_id" value="<?=$id?>"><button class="btn btn-ghost btn-sm"><?=is_review_liked((int)$review['id'])?'♥':'♡'?> <?=(int)$review['likes']?> likes</button></form><?php else:?><small>♡ <?=(int)$review['likes']?> likes</small><?php endif;?><?php if(is_logged_in()&&(int)$review['user_id']!==(int)current_user()['id']):?><details style="margin-top:10px"><summary class="form-help" style="cursor:pointer">Report this review</summary><form method="post" action="<?=url('report.php')?>" class="action-row" style="margin-top:8px"><?=csrf_field()?><input type="hidden" name="gem_id" value="<?=$id?>"><input type="hidden" name="review_id" value="<?=(int)$review['id']?>"><select class="form-control" name="violation_type" required style="max-width:230px"><option value="">Select reason</option><option>Harassment or hate</option><option>Spam or advertising</option><option>False information</option><option>Inappropriate content</option></select><button class="btn btn-danger btn-sm">Report</button></form></details><?php endif;?></article><?php endforeach;else:?><div class="empty-state"><p>No approved reviews yet. Be the first to share your experience.</p></div><?php endif;?></div></div>
</main><aside><div class="sidebar-sticky"><div class="content-card"><h3>Plan your visit</h3><p class="muted">Shared by <?=e($gem['contributor_name'])?></p><a class="btn btn-primary btn-block" href="<?=is_logged_in()?url('review.php?gem_id='.$id):url('login.php')?>">Share Your Experience</a><?php if(is_logged_in()):?><form method="post" action="<?=url('report.php')?>" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="gem_id" value="<?=$id?>"><select class="form-control" name="violation_type" required><option value="">Report an issue…</option><option>Incorrect information</option><option>Inappropriate content</option><option>Duplicate listing</option><option>Closed permanently</option></select><textarea class="form-control" name="details" placeholder="Optional details" maxlength="400" style="margin-top:8px;min-height:80px"></textarea><button class="btn btn-ghost btn-block btn-sm" style="margin-top:8px">Submit Report</button></form><?php endif;?></div></div></aside></div></div>
